#[test]
fn reader_operation_matches_native_vocabulary() {
    for (member, raw, name) in [
        (ReaderOperation::Tag, 0, "tag"),
        (ReaderOperation::Length, 1, "length"),
        (ReaderOperation::Value, 2, "value"),
        (ReaderOperation::Trailer, 3, "trailer"),
        (ReaderOperation::Header, 4, "header"),
    ] {
        assert_eq!(member.name(), name);
        assert_eq!(member.as_raw(), raw);
        assert_eq!(ReaderOperation::from_raw(raw), member);
    }
    let beyond = ReaderOperation::from_raw(5);
    assert_eq!((beyond.as_raw(), beyond.name()), (5, "unknown"));
}

